 jsonb_build_array('شناسایی ریسک ترکیبی لغزندگی ناشی از مواد پوششی با کار در ارتفاع، نه فقط ریسک سقوط عمومی'),
 jsonb_build_array('استفاده از مهار سقوط استاندارد بدون توجه به لغزندگی سطح از مواد پاشیده‌شده','نادیده گرفتن پایداری سکوی موقت پیش از شروع کار'),
