('mechanical_piping_supervisor','JUDGMENT','تصمیم درباره کیفیت جوش لوله مشکوک در بازرسی نهایی','L4',
 'در بازرسی نهایی پیش از تحویل، سرپرست یک ناپیوستگی مرزی در یک جوش پنهان‌شده زیر عایق حرارتی مشاهده می‌کند که رفع آن نیازمند باز کردن عایق و تاخیر قابل توجه است. تیم اجرایی می‌گوید احتمالاً در تلورانس است. سرپرست چه تصمیمی می‌گیرد؟',
 'ادامه بستن‌بندی را متوقف می‌کند و رادیوگرافی/آزمون غیرمخرب مجدد آن جوش خاص را الزامی می‌داند؛ «احتمالاً در تلورانس است» یک حدس است نه شواهد مستند، و پوشاندن جوش مشکوک با عایق بدون تایید قطعی، بازرسی و تعمیر احتمالی بعدی را بسیار پرهزینه‌تر و پیچیده‌تر می‌کند.',
 jsonb_build_array('توقف بستن‌بندی تا تایید قطعی وضعیت جوش مشکوک','الزام آزمون غیرمخرب مجدد به‌جای پذیرش حدس تیم اجرایی','آگاهی از هزینه به‌مراتب بالاتر کشف مشکل پس از دفن/پوشش','مستندسازی کامل نتیجه نهایی برای پرونده فنی تحویل'),
 jsonb_build_array('اولویت‌دهی به قطعیت مستند بر برآورد ظاهری تیم اجرایی در تصمیم نهایی تحویل'),
 jsonb_build_array('پذیرش جوش مشکوک بر مبنای حدس «احتمالاً خوب است» برای جلوگیری از تاخیر','عدم مستندسازی تصمیم نهایی درباره جوش مشکوک'),
 'ASME B31.3 / رویه بازرسی نهایی پیش از تحویل'),

('civil_supervisor','JUDGMENT','تصمیم درباره ترک‌خوردگی مشاهده‌شده در سازه بتنی تازه','L4',
 'چند روز پس از بازکردن قالب یک عضو بتنی باربر، سرپرست ترک‌های موئی در سطح آن مشاهده می‌کند. تیم اجرایی می‌گوید ترک‌های سطحی معمول‌اند و مشکلی ندارد. سرپرست چگونه تصمیم می‌گیرد؟',
 'به‌جای پذیرش یا رد بدون بررسی، الگوی ترک (عمق، جهت، گستردگی) را مستند و با مهندس سازه/کنترل کیفیت بررسی می‌کند تا مشخص شود ترک سطحی بی‌خطر (جمع‌شدگی) است یا نشانه مشکل سازه‌ای عمیق‌تر (مانند مشکل طراحی مخلوط یا بارگذاری زودهنگام)؛ تصمیم پذیرش یا رد را بر مبنای نظر مهندسی مستند می‌گیرد، نه برداشت تیم اجرایی.',
 jsonb_build_array('مستندسازی دقیق الگوی ترک پیش از هر قضاوت','ارجاع به مهندس سازه/کنترل کیفیت برای ارزیابی ریشه‌ای','عدم پذیرش خودکار توجیه «ترک سطحی معمول است»','تصمیم نهایی پذیرش/رد بر مبنای نظر مهندسی مستند'),
 jsonb_build_array('تفکیک دقیق بین ترک جمع‌شدگی بی‌خطر و نشانه احتمالی مشکل سازه‌ای عمیق‌تر'),
 jsonb_build_array('پذیرش فوری توضیح تیم اجرایی بدون بررسی مهندسی مستقل','عدم مستندسازی الگوی ترک برای پیگیری آینده'),
 'ACI 224 / رویه ارزیابی کیفیت سازه بتنی'),

('civil_supervisor','JUDGMENT','قضاوت درباره اختلاف تفسیر نقشه اجرایی','L2',
 'دو نقشه اجرایی (معماری و سازه) برای همان جزئیات اتصال، مشخصات کمی متفاوت نشان می‌دهند و تیم اجرایی نمی‌داند کدام را رعایت کند. سرپرست چگونه تصمیم می‌گیرد؟',
 'به‌جای انتخاب دلبخواهی یکی از نقشه‌ها، موضوع را فوراً به‌صورت درخواست اطلاعات (RFI) به تیم طراحی ارجاع می‌دهد و کار آن جزئیات خاص را تا دریافت پاسخ رسمی متوقف می‌کند؛ اجرای بر مبنای حدس می‌تواند بعداً نیازمند اصلاح پرهزینه شود.',
 jsonb_build_array('عدم انتخاب دلبخواهی بین دو نقشه متناقض','ارجاع فوری به‌صورت RFI رسمی به تیم طراحی','توقف اجرای آن جزئیات خاص تا دریافت پاسخ رسمی','مستندسازی تناقض و پاسخ نهایی برای سوابق پروژه'),
 jsonb_build_array('رعایت مسیر رسمی حل تناقض طراحی به‌جای تصمیم‌گیری یک‌جانبه اجرایی'),
 jsonb_build_array('انتخاب یکی از دو نقشه بر مبنای حدس بدون ارجاع رسمی','ادامه اجرا بدون توقف تا روشن شدن تناقض'),
 'رویه مدیریت RFI و اسناد طراحی پروژه'),

('coating_supervisor','JUDGMENT','تصمیم درباره نتیجه ضخامت‌سنجی مرزی پوشش خشک','L4',
 'اندازه‌گیری ضخامت فیلم خشک (DFT) پوشش نهایی در چند نقطه اندکی کمتر از حداقل مشخصات فنی است، در حالی که میانگین کلی ناحیه در محدوده مجاز است. تیم اجرایی می‌گوید میانگین قابل قبول کافی است. سرپرست چگونه تصمیم می‌گیرد؟',
 'صرف قابل قبول بودن میانگین را کافی نمی‌داند؛ استانداردهای رایج پوشش معمولاً حداقل نقطه‌ای (Minimum Spot Reading) را نیز الزامی می‌دانند، چون نقاط نازک‌تر از حداقل می‌توانند کانون خوردگی زودرس شوند. لایه تکمیلی در نقاط زیر حداقل را الزامی می‌کند، نه فقط اتکا به میانگین ناحیه.',
 jsonb_build_array('عدم پذیرش صرف میانگین قابل قبول به‌عنوان معیار کافی','الزام رعایت حداقل نقطه‌ای طبق استاندارد پوشش','الزام لایه تکمیلی در نقاط زیر حداقل مجاز','آگاهی از ریسک کانون خوردگی زودرس در نقاط نازک'),
 jsonb_build_array('دانش فنی دقیق درباره تفاوت معیار میانگین ناحیه‌ای و حداقل نقطه‌ای در پذیرش ضخامت پوشش'),
 jsonb_build_array('پذیرش ناحیه فقط بر مبنای میانگین قابل قبول بدون بررسی حداقل نقطه‌ای','عدم الزام لایه تکمیلی در نقاط مشخص زیر حداقل'),
 'SSPC-PA2 / مشخصات فنی پوشش پروژه'),

('coating_supervisor','JUDGMENT','قضاوت درباره تاخیر تامین رنگ نهایی رنگ‌آمیزی','L2',
 'رنگ نهایی (Top Coat) با رنگ سفارشی کارفرما هنوز تامین نشده و تیم اجرایی پیشنهاد می‌دهد لایه میانی به‌عنوان پوشش موقت «نهایی» تلقی و کار به مرحله بعد برود. سرپرست چگونه تصمیم می‌گیرد؟',
 'این پیشنهاد را بدون تایید رسمی نمی‌پذیرد؛ عدم تکمیل سیستم پوشش طبق مشخصات فنی (شامل رنگ و ضخامت لایه نهایی) می‌تواند نیازمند بازگشایی/آماده‌سازی مجدد سطح پس از تامین رنگ باشد. یا تامین رنگ را تسریع می‌کند یا تایید کتبی مهندسی برای توالی جایگزین کار می‌گیرد، نه تصمیم یک‌جانبه خودش یا تیم اجرایی.',
 jsonb_build_array('عدم پذیرش لایه میانی به‌عنوان نهایی بدون تایید رسمی مهندسی','پیگیری تسریع تامین رنگ نهایی به‌عنوان اولویت','دریافت تایید کتبی برای هرگونه توالی جایگزین کار','آگاهی از ریسک آماده‌سازی مجدد سطح در صورت تاخیر بیش از حد لایه نهایی'),
 jsonb_build_array('تفکیک روشن بین راه‌حل موقت غیررسمی و تغییر رسمی تاییدشده در توالی اجرای پوشش'),
 jsonb_build_array('پذیرش خودسرانه لایه میانی به‌عنوان لایه نهایی بدون تایید مهندسی','ادامه کارهای بعدی بدون پیگیری جدی تامین رنگ نهایی'),
 'مشخصات فنی سیستم پوشش پروژه'),

('contract_commercial_manager','JUDGMENT','تصمیم درباره درخواست تمدید زمان (EOT) با مستندات ناقص','L4',
 'پیمانکار درخواست تمدید زمان (EOT) قابل‌توجهی به همراه ادعای مالی مرتبط ارائه کرده، اما تحلیل مسیر بحرانی (Delay Analysis) پیوست، ناقص و غیرمنطبق با روش مورد قبول قرارداد است. تحت فشار زمانی برای پاسخ به پیمانکار، مدیر قراردادها چه تصمیمی می‌گیرد؟',
 'درخواست را با تحلیل ناقص تایید یا رد قطعی نمی‌کند؛ رسماً به پیمانکار اعلام می‌کند تحلیل تاخیر باید با روش مورد قبول قرارداد (مثل روش تاثیر برنامه یا مشابه AACE RP) و مستندات کامل ارائه شود، و مهلت مشخصی برای ارائه مجدد تعیین می‌کند تا از رد یا تایید ناآگاهانه یک ادعای بزرگ مالی جلوگیری شود.',
 jsonb_build_array('عدم تایید یا رد قطعی EOT بر مبنای تحلیل تاخیر ناقص','الزام ارائه تحلیل با روش مورد قبول قرارداد و مستندات کامل','تعیین مهلت مشخص برای ارائه مجدد تحلیل کامل','اجتناب از تصمیم ناآگاهانه درباره ادعای مالی بزرگ'),
 jsonb_build_array('پایبندی روشمند به الزام کیفیت تحلیل تاخیر پیش از هر تصمیم مالی بزرگ'),
 jsonb_build_array('رد سریع ادعا فقط به بهانه ناقص بودن بدون فرصت اصلاح رسمی','تایید ادعای بزرگ مالی بر مبنای تحلیل ناقص برای رفع فشار زمانی'),
 'AACE RP 29R-03 / رویه بررسی ادعای تاخیر و EOT'),

('contract_commercial_manager','JUDGMENT','قضاوت درباره پیشنهاد تغییر روش پرداخت پیمانکار','L2',
 'پیمانکار در میانه پروژه درخواست تغییر روش پرداخت از پیشرفت فیزیکی تاییدشده به پیش‌پرداخت‌های دوره‌ای ثابت را دارد، با استدلال بهبود جریان نقدی. مدیر قراردادها چگونه تصمیم می‌گیرد؟',
 'این تغییر را بدون بررسی کامل اثر آن بر اهرم کنترلی کارفرما نمی‌پذیرد؛ روش پرداخت مبتنی بر پیشرفت تاییدشده ابزار کنترلی مهمی برای اطمینان از تطابق پرداخت با کار واقعی انجام‌شده است. در صورت تمایل به کمک به جریان نقدی پیمانکار، گزینه‌های جایگزین با کنترل کافی (مانند تسریع تایید صورت‌وضعیت) را بررسی می‌کند.',
 jsonb_build_array('عدم پذیرش تغییر بدون بررسی اثر بر اهرم کنترلی کارفرما','آگاهی از نقش کنترلی پرداخت مبتنی بر پیشرفت تاییدشده','بررسی گزینه جایگزین با کنترل کافی به‌جای پذیرش کامل درخواست','هماهنگی با مدیریت پروژه پیش از هرگونه تغییر ساختار پرداخت'),
 jsonb_build_array('حفظ اهرم کنترلی پرداخت به‌عنوان ابزار مدیریت ریسک اجرای پیمانکار'),
 jsonb_build_array('پذیرش کامل درخواست تغییر روش پرداخت صرفاً بر مبنای استدلال پیمانکار','عدم هماهنگی با مدیریت پروژه پیش از تغییر ساختار مالی قرارداد'),
 'رویه مدیریت پرداخت و صورت‌وضعیت پروژه');
